#include <string>
#include <vector>

class Playlist {
public:
    void add(std::string title) { songs_.push_back(std::move(title)); }
    std::size_t size() const { return songs_.size(); }
private:
    std::string name_;
    std::vector<std::string> songs_;       // owns and copies its elements.
};                                          // Rule of Zero: no copy code written.

int main() {
    Playlist a;
    a.add("Song A");
    Playlist b = a;          // copy construction: independent vector.
    b.add("Song B");         // a.size() == 1, b.size() == 2.
    a = b;                   // copy assignment: a now has 2, still independent.
}

// Danger: raw owning pointer.
struct Buffer {
    char* data = new char[100];
    ~Buffer() { delete[] data; }
};  // generated copy duplicates the ADDRESS: two deletes of one block.
```

| Member type | Generated copy does |
|---|---|
| `int`, `double`. | copies the value. |
| `std::string`, `std::vector`. | deep copy of contents. |
| raw owning `T*`. | copies the address only: shared, double delete. |

```reveal
{"prompt": "How do you fix Buffer without writing copy operations?", "answer": "Replace char* data with std::vector<char> data(100) (or std::string). The vector knows how to copy and free itself, so the generated operations become correct."}
